PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "core_coupon" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "discount_percent" integer NOT NULL, "is_active" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "core_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "role" varchar(20) NOT NULL, "phone" varchar(20) NULL, "avatar" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "core_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_cart" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customer_id" bigint NOT NULL UNIQUE REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "restaurant_id" bigint NULL REFERENCES "core_restaurant" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_driver" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "vehicle_type" varchar(50) NOT NULL, "license_plate" varchar(50) NOT NULL, "is_online" bool NOT NULL, "current_lat" decimal NULL, "current_lng" decimal NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_cartitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer NOT NULL, "cart_id" bigint NOT NULL REFERENCES "core_cart" ("id") DEFERRABLE INITIALLY DEFERRED, "food_item_id" bigint NOT NULL REFERENCES "core_fooditem" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_notification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(100) NOT NULL, "message" text NOT NULL, "is_read" bool NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_delivery" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "pickup_time" datetime NULL, "delivery_time" datetime NULL, "status" varchar(20) NOT NULL, "driver_id" bigint NULL REFERENCES "core_driver" ("id") DEFERRABLE INITIALLY DEFERRED, "order_id" bigint NOT NULL UNIQUE REFERENCES "core_order" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_orderitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer NOT NULL, "price" decimal NOT NULL, "food_item_id" bigint NULL REFERENCES "core_fooditem" ("id") DEFERRABLE INITIALLY DEFERRED, "order_id" bigint NOT NULL REFERENCES "core_order" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_payment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "method" varchar(50) NOT NULL, "amount" decimal NOT NULL, "status" varchar(20) NOT NULL, "transaction_id" varchar(100) NOT NULL, "order_id" bigint NOT NULL UNIQUE REFERENCES "core_order" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "status" varchar(20) NOT NULL, "total_amount" decimal NOT NULL, "special_instructions" text NOT NULL, "created_at" datetime NOT NULL, "address_id" bigint NULL REFERENCES "core_address" ("id") DEFERRABLE INITIALLY DEFERRED, "customer_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "restaurant_id" bigint NOT NULL REFERENCES "core_restaurant" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_foodcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "restaurant_id" bigint NOT NULL REFERENCES "core_restaurant" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_review" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rating" integer NOT NULL, "comment" text NOT NULL, "created_at" datetime NOT NULL, "order_id" bigint NOT NULL UNIQUE REFERENCES "core_order" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_restaurant" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "description" text NOT NULL, "address" text NOT NULL, "phone" varchar(20) NOT NULL, "banner" varchar(100) NULL, "rating" decimal NOT NULL, "delivery_time_min" integer NOT NULL, "delivery_time_max" integer NOT NULL, "delivery_fee" decimal NOT NULL, "is_active" bool NOT NULL, "owner_id" bigint NOT NULL UNIQUE REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "category_id" bigint NULL REFERENCES "core_restaurantcategory" ("id") DEFERRABLE INITIALLY DEFERRED, "logo" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "core_restaurantcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "image" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "core_liveitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "description" text NOT NULL, "price" decimal NULL, "is_live" bool NOT NULL, "created_at" datetime NOT NULL, "image" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_address" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "street" varchar(255) NOT NULL, "city" varchar(100) NOT NULL, "state" varchar(100) NOT NULL, "zip_code" varchar(20) NOT NULL, "is_default" bool NOT NULL, "lat" decimal NULL, "lng" decimal NULL, "user_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "title" varchar(50) NOT NULL);
CREATE TABLE IF NOT EXISTS "core_fooditem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "description" text NOT NULL, "price" decimal NOT NULL, "image" varchar(100) NULL, "is_available" bool NOT NULL, "category_id" bigint NOT NULL REFERENCES "core_foodcategory" ("id") DEFERRABLE INITIALLY DEFERRED, "ingredients" varchar(255) NOT NULL, "is_popular" bool NOT NULL, "rating" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "core_favorite" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customer_id" bigint NOT NULL REFERENCES "core_user" ("id") DEFERRABLE INITIALLY DEFERRED, "created_at" datetime NOT NULL, "food_item_id" bigint NULL REFERENCES "core_fooditem" ("id") DEFERRABLE INITIALLY DEFERRED, "restaurant_id" bigint NULL REFERENCES "core_restaurant" ("id") DEFERRABLE INITIALLY DEFERRED);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
