INSERT INTO core_restaurant VALUES(2,'Bella Italia Pizzeria','Authentic wood-fired Neapolitan sourdough pizza baked at 900 degrees with San Marzano tomatoes and fior di latte mozzarella.','Street 308, Chamkarmon, Phnom Penh','+855 23 777 222','',4.9,25,40,2,1,5,1,'');
INSERT INTO core_restaurant VALUES(3,'Tokyo Ramen Master','Slow-simmered 18-hour pork bone tonkotsu broth, springy handcrafted alkaline noodles, and tender sous-vide chashu pork.','Street 63, BKK1, Phnom Penh','+855 23 666 333','',4.7,25,40,1.8,1,6,3,'');
INSERT INTO core_restaurant VALUES(4,'Golden Seoul Fried Chicken','Ultra-crispy double-fried Korean fried chicken glazed in finger-licking sweet soy garlic or fiery gochujang sauce.','Russian Boulevard, Tuol Kouk, Phnom Penh','+855 23 555 444','',4.8,20,35,1.5,1,7,4,'');
INSERT INTO core_restaurant VALUES(5,'Green Vitality Salad Bar','Farm-fresh organic superfood bowls, cold-pressed vegetable juices, and wholesome protein plates.','Street 240, Chey Chumneah, Phnom Penh','+855 23 444 555','',4.6,15,30,1.2,1,8,5,'');
INSERT INTO core_restaurant VALUES(6,'Kravanh Khmer Heritage','Royal Cambodian recipes passed down through generations. Fresh local kroeung, wild fish amok & lok lak.','Street 240, Daun Penh, Phnom Penh','+855 23 999 101','',4.9,20,35,1.2,1,10,7,'');
