INSERT INTO core_fooditem VALUES(1,'Classic Angus Cheeseburger','Double smashed 100% Angus beef patties, aged cheddar cheese, caramelized onions, crisp lettuce, tomato, and secret truffle mayo on a toasted brioche bun.',8.99,'',1,1,'Angus Beef, Cheddar, Onions, Brioche, Truffle Mayo, Lettuce',1,4.9);
INSERT INTO core_fooditem VALUES(2,'Smoky BBQ Bacon Burger','Flame-grilled prime beef patty topped with smoked applewood bacon, melted cheddar, crispy onion rings, and tangy chipotle BBQ sauce.',9.99,'',1,1,'Beef, Bacon, Cheddar, Onion Rings, BBQ Sauce',1,4.8);
INSERT INTO core_fooditem VALUES(3,'Spicy Jalapeño Crunch Burger','Juicy beef patty infused with pepper jack cheese, pickled jalapeños, crispy corn chips, and spicy avocado lime aioli.',8.5,'',1,1,'Beef, Pepper Jack, Jalapeños, Tortilla Strips, Aioli',0,4.6);
INSERT INTO core_fooditem VALUES(4,'Truffle Mushroom Swiss Burger','Sautéed forest mushrooms, melted Swiss cheese, fresh arugula, and rich black truffle cream on garlic buttered brioche.',10.5,'',1,1,'Beef, Swiss Cheese, Wild Mushrooms, Truffle Cream',1,4.9);
INSERT INTO core_fooditem VALUES(5,'Truffle Parmesan Fries','Hand-cut Idaho potato fries tossed with white truffle oil, grated parmesan, and chopped fresh parsley.',4.5,'',1,2,'Potatoes, Truffle Oil, Parmesan, Herbs',1,4.7);
INSERT INTO core_fooditem VALUES(6,'Oreo Cream Milkshake','Thick and creamy vanilla ice cream shake blended with real Oreo cookies and topped with whipped cream.',4,'',1,2,'Vanilla Ice Cream, Milk, Oreo, Whipped Cream',0,4.8);
INSERT INTO core_fooditem VALUES(7,'Margherita D.O.P','San Marzano tomato sauce, fresh buffalo mozzarella, fragrant sweet basil leaves, and cold-pressed extra virgin olive oil.',11.99,'',1,3,'San Marzano Tomato, Mozzarella, Basil, Olive Oil',1,4.9);
INSERT INTO core_fooditem VALUES(8,'Diavola Pepperoni Hot','Spicy Calabrian salami, crushed red chili flakes, roasted red peppers, mozzarella, and honey drizzle.',13.5,'',1,3,'Spicy Salami, Mozzarella, Tomato Sauce, Chili, Honey',1,4.8);
INSERT INTO core_fooditem VALUES(9,'Quattro Formaggi Supreme','Four artisanal cheeses: fresh mozzarella, sharp gorgonzola dolce, creamy fontina, and aged parmigiano-reggiano.',14,'',1,3,'Mozzarella, Gorgonzola, Fontina, Parmigiano',0,4.7);
INSERT INTO core_fooditem VALUES(10,'Prosciutto & Wild Rocket','Prosciutto di Parma aged 24 months, wild baby rocket, shaved parmesan, cherry tomatoes, and balsamic reduction.',15,'',1,3,'Prosciutto, Arugula, Parmesan, Tomatoes, Balsamic',1,4.9);
INSERT INTO core_fooditem VALUES(11,'Rich Tonkotsu Black Garlic Ramen','18-hour pork marrow broth, roasted black garlic mayu oil, tender chashu, ajitsuke tamago egg, and nori seaweed.',9.99,'',1,4,'Pork Broth, Ramen Noodles, Chashu, Egg, Black Garlic Oil',1,4.9);
INSERT INTO core_fooditem VALUES(12,'Spicy Miso Red Dragon Ramen','Fermented Hokkaido red miso broth with chili tare, minced pork, bamboo shoots, scallions, and soft-boiled egg.',10.5,'',1,4,'Spicy Miso Broth, Ground Pork, Egg, Scallions, Nori',1,4.8);
INSERT INTO core_fooditem VALUES(13,'Crispy Chicken Gyoza (6 pcs)','Pan-seared Japanese dumplings packed with minced chicken, cabbage, and scallions, served with spicy sesame ponzu.',4.99,'',1,4,'Chicken, Cabbage, Ginger, Garlic, Soy Sauce',0,4.6);
